#pragma once
#include <stdint.h>

namespace carb
{
namespace ujitso
{

// Various opaque handles
// For all of them value == 0 is an invalid handle

// An opaque handle pointing to a request that can be used to retrieve results of a build request
// the lifetime of a handle is maintained inside the agent, so that an invalid handle can be used (calls will return OperationResult::INVALIDHANDLE_ERROR)
struct RequestHandle
{
    uint64_t value; // opaque value
};
inline bool operator==(const RequestHandle& a, const RequestHandle& b)
{
    return a.value == b.value;
}

// An opaque handle pointing to a specific result of a build request that can be used to retrieve individual results of a build request
// the lifetime of a handle is maintained inside the agent, so that an invalid handle can be used (calls will return OperationResult::INVALIDHANDLE_ERROR)
struct ResultHandle
{
    uint64_t value; // opaque value
};

// opaque handle pointing to a request in the UJITSO build process
struct DependencyHandle
{
    uint64_t value;
};
// opaque handle pointing to a request in the UJITSO build process
struct BuildHandle
{
    uint64_t value;
};

struct ContainerHandle
{
    uint64_t value;
};

struct DedupedContainerHandle
{
    uint64_t value;
};

}
}